from __future__ import annotations

from decimal import Decimal, localcontext, ROUND_HALF_UP
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0")


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    """Apply legacy empty/null-to-zero numeric coercion."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(value)


def _precision_for(*values: Decimal, extra: int = 32) -> int:
    precision = extra
    for value in values:
        exponent = value.as_tuple().exponent
        precision += len(value.as_tuple().digits) + abs(exponent)
    return max(28, precision)


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENT, rounding=ROUND_HALF_UP)


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    result = dict(order)

    if new_status == "I":
        return result, [], []

    if new_status == "X":
        result["STAT_CD"] = "X"
        return result, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    result_order = dict(order)
    result_lines = [dict(line) for line in lines]

    if order.get("STAT_CD") in ("I", "X"):
        return result_order, result_lines, []

    live_values: list[tuple[int, Decimal, Decimal]] = []
    context_values: list[Decimal] = []

    for index, line in enumerate(lines):
        if line.get("DEL_FLG", "") == "Y":
            continue

        quantity = _numeric(line.get("QTY"))
        unit_price = _numeric(line.get("UNIT_PRC"))
        live_values.append((index, quantity, unit_price))
        context_values.extend((quantity, unit_price))

    discount = _numeric(order.get("DISC_PCT"))
    stored_total = _numeric(order.get("TOT_AMT"))
    context_values.extend((discount, stored_total))

    with localcontext() as context:
        context.prec = _precision_for(*context_values)

        total = _ZERO
        for index, quantity, unit_price in live_values:
            extended_amount = _round_cents(quantity * unit_price)
            result_lines[index]["EXT_AMT"] = float(extended_amount)
            total += extended_amount

        discounted_total = _round_cents(
            total * (Decimal("100") - discount) / Decimal("100")
        )

    result_order["TOT_AMT"] = float(discounted_total)
    audits = ["ORD_RETOTAL"] if stored_total != discounted_total else []

    return result_order, result_lines, audits
